INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (96, 242, 'BOPP FILM + COATING EVA GLUE', '../upload/image/20180928/20180928234310_31011.jpg', '<p><strong>BOPP Thermal Lamination Film (glossy and matte lamination)</strong></p><div class="mceSectionContainer" id="ali-anchor-AliPostDhMb-5wpe5" style="color:#3A3A3A;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <div style="padding:10px 0px;"> <p style="text-align:center;"> <span style="color:#FF0000;line-height:48px;font-size:32px;background-color:#FFFF00;"><strong>BOPP FILM + COATING EVA GLUE</strong></span></p> <p></p> <p><span style="line-height:27px;font-size:18px;">BOPP/BOPET/BOPA Thermal Lamination Film (glossy/matte) which were <span style="color:#FF0000;line-height:36px;font-size:24px;background-color:#FFFF00;">BOPP clear film coated with EVA.</span></span></p> <p></p> <p><span style="color:#FF0000;line-height:36px;font-size:24px;background-color:#FFFF00;">EVA coating film (BOPP thermal laminating Film)</span></p> <p><span style="line-height:27px;font-size:18px;">Eva coating film (BOPP thermal laminating Film) glossy/matte were bopp bopet,bopa film coated with EVA on the surface, which were widely used in packaging lines such as: all kinds of wine boxes.</span></p> <p><span style="line-height:27px;font-size:18px;">Eva coating film included BOPET thermal film,BOPA thermal film, bopp thermal film</span></p> <p></p> <p><span style="line-height:27px;font-size:18px;">Our goods features: high clarity, wearable on surface, durability good bonding.</span></p> <p></p> <p><span style="color:#FF0000;line-height:27px;font-size:18px;background-color:#FFFF00;">General Thickness: 25,28 microns</span><br/> <span style="color:#FF0000;line-height:27px;font-size:18px;background-color:#FFFF00;">BOPET/BOPA/BOPP thickness : 20,18,15,12,10 microns</span><br/> <span style="color:#FF0000;line-height:27px;font-size:18px;background-color:#FFFF00;">EVA thickness:12,10,8,4 microns</span><br/> <span style="color:#FF0000;line-height:27px;font-size:18px;background-color:#FFFF00;">Width: 400-1800mm Length: 200-3000m</span><br/> <span style="color:#FF0000;line-height:27px;font-size:18px;background-color:#FFFF00;">Paper core : 25.4mm, 76mm (3" ,1.5" 2")</span></p> <p><br/> <span style="line-height:27px;font-size:18px;">Equipment for laminating film: dry and wet laminating film machine </span><br/> <span style="line-height:27px;font-size:18px;">Temperature: normal: 85-100C; special: 100-110C </span><br/> <span style="line-height:27px;font-size:18px;">Roller pressure: 8-15MPa Speed: 8-50m/min</span></p> <p><br/> <span style="line-height:27px;font-size:18px;">Remarks:special laminations are those with thicker ink, solid color, high moisture content and bigger size paper Applications:top-grade presswork,outdoor advertisement, non-drying adhesive, tags, electric cable, electronic products.</span></p> <p><br/></p><p><br/> <span style="color:#FF0000;line-height:36px;font-size:24px;"><strong>Applications:</strong></span></p> <p><span style="line-height:27px;font-size:18px;"><span style="color:#FF0000;background-color:#FFFF00;"><strong>Laminate the surface</strong> </span></span><span style="line-height:27px;font-size:18px;">of Books, catalogs, samples, posters, printed paper, Food, medicines, cosmetics, gifts, wine boxes and other packaging film ,Drawings, documents, ads, pictures, display boards, etc.</span></p> <p><img alt="QQ20140710101909.jpg" src="http://kfdown.s.aliimg.com/kf/HTB1yrmxGXXXXXaIXpXXq6xXFXXXi/221290553/HTB1yrmxGXXXXXaIXpXXq6xXFXXXi.jpg" style="border:0px currentColor;"/></p> </div> </div> <p style="color:#3A3A3A;text-indent:0px;font-family:arial, helvetica, sans-serif;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <img alt="IMG_0230.jpg" src="http://kfdown.s.aliimg.com/kf/HTB1WPaxGXXXXXcMXXXXq6xXFXXXr/221290553/HTB1WPaxGXXXXXcMXXXXq6xXFXXXr.jpg" style="bor